// ArticleFacade.kt L40-52 → updateArticle
func (s *articleFacadeImpl) UpdateArticle(ctx context.Context, request UpdateArticleRequest, slug string, author User) (ArticleView, error) {
    articleToUpdate, err := s.repo.FindBySlug(ctx, slug)
    if err != nil {
        return ArticleView{}, fmt.Errorf("find article by slug: %w", err)
    }

    if !articleToUpdate.IsAuthor(author) {
        return ArticleView{}, ErrInvalidRequest("only author can update article")
    }

    updateUser(request, articleToUpdate)

    savedArticle, err := s.repo.Save(ctx, articleToUpdate)
    if err != nil {
        return ArticleView{}, fmt.Errorf("save article: %w", err)
    }

    return savedArticle.ToAuthorArticleView(author), nil
}

// ArticleFacade.kt L53-62 → deleteArticle
func (s *articleFacadeImpl) DeleteArticle(ctx context.Context, slug string, user User) error {
    article, err := s.repo.FindBySlug(ctx, slug)
    if errors.Is(err, ErrNotFound) {
        return fmt.Errorf("delete article: %w", ErrNotFound)
    }
    if err != nil {
        return fmt.Errorf("delete article: %w", err)
    }

    if !article.IsAuthor(user) {
        return fmt.Errorf("delete article: %w", ErrInvalidRequest)
    }

    if err := s.repo.DeleteBySlug(ctx, slug); err != nil {
        return fmt.Errorf("delete article: %w", err)
    }
    return nil
}

