// ArticleFacade.kt L79-85 → feed
func (s *articleFacadeImpl) Feed(ctx context.Context, offset int64, limit int, user User) (MultipleArticlesView, error) {
    articles, err := s.repo.FindNewestArticlesByAuthorIds(ctx, user.FollowingIDs, offset, limit)
    if err != nil {
        return MultipleArticlesView{}, fmt.Errorf("feed: %w", err)
    }
    var articleViews []ArticleView
    for _, article := range articles {
        articleView := mapToArticleView(article, user)
        articleViews = append(articleViews, articleView)
    }
    return toMultipleArticlesView(articleViews), nil
}

