// ArticleFacade.kt L104-110 → unfavoriteArticle
func (s *articleFacadeImpl) UnfavoriteArticle(ctx context.Context, slug string, currentUser User) (ArticleView, error) {
    article, err := s.articleRepo.FindBySlug(ctx, slug)
    if err != nil {
        return ArticleView{}, fmt.Errorf("find article by slug: %w", err)
    }

    if err := currentUser.Unfavorite(article); err != nil {
        return ArticleView{}, fmt.Errorf("unfavorite article: %w", err)
    }

    if err := s.userRepo.Save(ctx, currentUser); err != nil {
        return ArticleView{}, fmt.Errorf("save user: %w", err)
    }

    return s.mapToArticleView(article, currentUser), nil
}

